def experiment(inputs):
    history = inputs.get('history', [])
    results = []
    for t in history:
        try:
            is_valid = isinstance(t, (type(None), dict)) and (('transition_id' in t) if isinstance(t, dict) else True)
            results.append(1.0 if is_valid else 0.0)
        except Exception:
            results.append(0.0)
    return {'measurements': {'accuracy': results if results else [0.0]}}
